CREATE TABLE IF NOT EXISTS diary3_clock (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL);
INSERT OR IGNORE INTO diary3_clock VALUES (1, 0);
CREATE TABLE IF NOT EXISTS diary3_records (key TEXT PRIMARY KEY, data TEXT NOT NULL, revision INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS diary3_revision ON diary3_records(revision);
CREATE TRIGGER IF NOT EXISTS diary3_insert AFTER INSERT ON diary3_records BEGIN UPDATE diary3_clock SET revision=NEW.revision WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS diary3_update AFTER UPDATE OF data ON diary3_records BEGIN UPDATE diary3_clock SET revision=NEW.revision WHERE id=1; END;
CREATE TABLE IF NOT EXISTS diary3_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS diary3_x (id TEXT PRIMARY KEY, kind TEXT NOT NULL, parent TEXT NOT NULL DEFAULT '', state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL DEFAULT 0, buffer_id TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS diary3_substack (id TEXT PRIMARY KEY, kind TEXT NOT NULL, parent TEXT NOT NULL DEFAULT '', state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL DEFAULT 0, buffer_id TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS diary3_threads (id TEXT PRIMARY KEY, kind TEXT NOT NULL, parent TEXT NOT NULL DEFAULT '', state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL DEFAULT 0, buffer_id TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS diary3_obsidian (id TEXT PRIMARY KEY, entity TEXT NOT NULL, created_at TEXT NOT NULL, version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS diary3_login (key TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, window_start INTEGER NOT NULL DEFAULT 0, locked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS diary3_jobs (name TEXT PRIMARY KEY, next_at INTEGER NOT NULL DEFAULT 0, lease_until INTEGER NOT NULL DEFAULT 0, generation INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS diary3_jobs_due ON diary3_jobs(next_at);
